(() => {
'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
const ui={day:document.querySelector('#day'),hotbar:document.querySelector('#hotbar'),toast:document.querySelector('#toast'),hint:document.querySelector('#hint'),start:document.querySelector('#startScreen'),craft:document.querySelector('#craftScreen')};
let W=0,H=0,dpr=1,last=0,started=false,paused=false,toastTimer=0,dayTime=8.2,dayNo=1;
function resize(){dpr=Math.min(devicePixelRatio||1,1.6);W=innerWidth;H=innerHeight;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
const player={x:0,y:0,vx:0,vy:0,dir:0,hp:100,stam:100,food:70,swing:0,flash:0,step:0};
const bag={wood:0,stone:0,berry:0,axe:false,fire:0};let active=0;
const items=[{key:'axe',icon:'🪓',name:'Топор',count:()=>bag.axe?'1':'—'},{key:'stone',icon:'◈',name:'Камень',count:()=>bag.stone},{key:'wood',icon:'⌁',name:'Ветки',count:()=>bag.wood},{key:'berry',icon:'●',name:'Ягоды',count:()=>bag.berry},{key:'fire',icon:'♨',name:'Костёр',count:()=>bag.fire}];
function drawBar(){ui.hotbar.innerHTML=items.map((it,i)=>`<div class="slot ${i===active?'active':''}" data-i="${i}"><span class="slot-num">${i+1}</span>${it.icon}<span class="slot-count">${it.count()}</span><span class="slot-name">${it.name}</span></div>`).join('');}
drawBar();ui.hotbar.onclick=e=>{const s=e.target.closest('.slot');if(s){active=+s.dataset.i;drawBar()}};
let seed=241297;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}function hash(x,y){let n=Math.sin(x*127.1+y*311.7+12.9)*43758.5453;return n-Math.floor(n)}
const resources=[],trees=[],rocks=[],flowers=[],enemies=[],fires=[];
// Stable, hand-seeded woodland chunks around the spawn; the clearing is intentionally open.
for(let gx=-13;gx<=13;gx++)for(let gy=-13;gy<=13;gy++){let h=hash(gx,gy),x=gx*112+(hash(gx+8,gy)*54-27),y=gy*112+(hash(gx,gy-3)*54-27),dist=Math.hypot(x,y);if(dist<175)continue;
 if(h>.19){let size=.78+hash(gx-2,gy+4)*.58;trees.push({x,y,size,kind:hash(gx+6,gy)*3|0,tone:hash(gx+11,gy+3)})}
 if(h>.81&&dist>220)rocks.push({x:x+35,y:y-18,size:.7+hash(gx,gy+4)*.5});
 if(h<.24&&dist>185)flowers.push({x:x+(hash(gx+3,gy)*75-37),y:y+(hash(gx,gy+3)*75-37),tone:hash(gx+4,gy+6)});
}
// gatherables placed in walkable clearings, then replenish around the explored frontier
for(let i=0;i<86;i++){let a=rand()*Math.PI*2,r=155+rand()*930;resources.push({x:Math.cos(a)*r,y:Math.sin(a)*r,type:rand()<.48?'wood':rand()<.72?'stone':'berry',alive:true,phase:rand()*8})}
for(let i=0;i<9;i++){let a=rand()*Math.PI*2,r=390+rand()*800;enemies.push({x:Math.cos(a)*r,y:Math.sin(a)*r,hp:36,max:36,phase:rand()*8,alert:false})}
const keys={};addEventListener('keydown',e=>{let k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(!e.repeat){if(k==='e')gather();if(k===' '||k==='f')attack();if(k==='c')makeFire();if(k==='i'||k==='escape'){if(ui.start.classList.contains('hidden'))toggleCraft()};if(k>='1'&&k<='5'){active=+k-1;drawBar()}}});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
let joy={x:0,y:0,on:false,id:null};const joyEl=document.querySelector('#joy'),knob=document.querySelector('#knob');
joyEl.addEventListener('pointerdown',e=>{joy.on=true;joy.id=e.pointerId;joyEl.setPointerCapture(e.pointerId);joyMove(e)});joyEl.addEventListener('pointermove',e=>{if(joy.on&&e.pointerId===joy.id)joyMove(e)});function joyMove(e){let r=joyEl.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),m=Math.min(34,Math.hypot(dx,dy)),a=Math.atan2(dy,dx);joy.x=Math.cos(a)*m/34;joy.y=Math.sin(a)*m/34;knob.style.left=`calc(50% + ${joy.x*34}px)`;knob.style.top=`calc(50% + ${joy.y*34}px)`}function joyEnd(){joy.on=false;joy.x=joy.y=0;knob.style.left='50%';knob.style.top='50%'}joyEl.addEventListener('pointerup',joyEnd);joyEl.addEventListener('pointercancel',joyEnd);
document.querySelector('#attackBtn').addEventListener('pointerdown',e=>{e.preventDefault();attack()});document.querySelector('#gatherBtn').addEventListener('pointerdown',e=>{e.preventDefault();gather()});
let mouseDown=false;canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button===0){mouseDown=true;attack()}});canvas.addEventListener('pointerup',()=>mouseDown=false);
document.querySelector('#startBtn').onclick=()=>{started=true;ui.start.classList.add('hidden');say('Собери 5 веток и 3 камня')};document.querySelector('#closeCraft').onclick=()=>ui.craft.classList.add('hidden');document.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>craft(b.dataset.craft));
function say(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100)}
function nearbyResource(){return resources.filter(o=>o.alive&&Math.hypot(o.x-player.x,o.y-player.y)<82).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0]}
function gather(){let o=nearbyResource();if(!o){say('Поблизости ничего нет');return}o.alive=false;bag[o.type]++;if(o.type==='wood')say('Ветки подобраны  ·  '+bag.wood);else if(o.type==='stone')say('Камень подобран  ·  '+bag.stone);else{say('Сладкие ягоды  ·  +12 здоровья');player.hp=Math.min(100,player.hp+12);player.food=Math.min(100,player.food+8)}if(bag.wood>=5&&bag.stone>=3)document.querySelector('#questTitle').textContent='Костёр готов';drawBar();updateQuest()}
function updateQuest(){document.querySelector('#woodGoal').textContent=`${Math.min(5,bag.wood)} / 5`;document.querySelector('#stoneGoal').textContent=`${Math.min(3,bag.stone)} / 3`;if(bag.wood>=5&&bag.stone>=3){document.querySelector('#questDesc').textContent='Запасы собраны. Разожги костёр (C) и исследуй чащу.';document.querySelector('#goal').innerHTML='Зажги костёр <b>· C</b> &nbsp; Найди маяк <b>⌖</b>'}}
function nearestEnemy(){return enemies.filter(e=>e.hp>0&&Math.hypot(e.x-player.x,e.y-player.y)<120).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0]}
function attack(){if(!started||player.swing>0)return;if(player.stam<8){say('Нужно перевести дух');return}player.stam-=8;player.swing=.38;let target=nearestEnemy();if(target){target.hp-=bag.axe?24:13;target.alert=true;target.flash=.15;if(target.hp<=0){bag.berry+=1;bag.wood+=1;say('Серый карлик повержен · +1 ягода, +1 ветка');drawBar();updateQuest()}else say(bag.axe?'Точный удар топора!':'Удар попал!')}else say('Удар рассекает холодный воздух')}
function makeFire(){if(!started)return;if(bag.wood<5||bag.stone<2){say('Для костра нужно 5 веток и 2 камня');return}bag.wood-=5;bag.stone-=2;bag.fire++;fires.push({x:player.x+Math.cos(player.dir)*55,y:player.y+Math.sin(player.dir)*55,phase:rand()*8});say('Костёр разожжён · рядом становится теплее');updateQuest();drawBar()}
function toggleCraft(){ui.craft.classList.toggle('hidden')}
function craft(type){if(type==='axe'){if(bag.axe){say('Топор уже у тебя');return}if(bag.wood<3||bag.stone<2){say('Нужно 3 ветки и 2 камня');return}bag.wood-=3;bag.stone-=2;bag.axe=true;say('Кремнёвый топор готов! Урон увеличен')}else if(type==='fire')makeFire();else if(type==='potion'){if(bag.berry<3){say('Нужно 3 ягоды');return}bag.berry-=3;player.hp=Math.min(100,player.hp+40);player.food=Math.min(100,player.food+20);say('Ягодный настой восстановил силы')}drawBar();ui.craft.classList.add('hidden')}

function rr(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function screenPoint(x,y){return [W*.5+(x-player.x),H*.55+(y-player.y)]}
function pathStroke(){ctx.save();ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(-1450,980);ctx.bezierCurveTo(-1050,760,-1090,440,-680,270);ctx.bezierCurveTo(-315,120,-465,-100,-105,-270);ctx.bezierCurveTo(180,-405,65,-590,460,-850);ctx.bezierCurveTo(755,-1040,940,-940,1300,-1180);ctx.lineWidth=107;ctx.strokeStyle='#28312a';ctx.stroke();ctx.lineWidth=85;ctx.strokeStyle='#827a5b';ctx.stroke();ctx.lineWidth=2;ctx.strokeStyle='rgba(202,188,144,.11)';ctx.setLineDash([6,14]);ctx.stroke();ctx.restore()}
function drawGround(t){let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#1a2b2c');sky.addColorStop(.38,'#35443a');sky.addColorStop(1,'#40503d');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
 // softly varied ground pools, seeded in world space
 for(let gx=-8;gx<9;gx++)for(let gy=-8;gy<9;gy++){let wx=gx*210,wy=gy*210,[sx,sy]=screenPoint(wx,wy),j=hash(gx,gy);if(sx<-180||sx>W+180||sy<-180||sy>H+180)continue;let r=80+j*130;let g=ctx.createRadialGradient(sx,sy,8,sx,sy,r);g.addColorStop(0,j>.5?'rgba(130,131,82,.12)':'rgba(24,49,42,.16)');g.addColorStop(1,'rgba(20,37,32,0)');ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(sx,sy,r*1.1,r*.7,j,0,Math.PI*2);ctx.fill()}
 ctx.save();ctx.translate(W*.5-player.x,H*.55-player.y);pathStroke();ctx.restore();
 // patches of fern, grass and lichen
 for(let i=0;i<140;i++){let wx=(Math.floor((player.x+Math.sin(i*17)*850)/100))*100+Math.sin(i*41)*48,wy=(Math.floor((player.y+Math.cos(i*13)*720)/100))*100+Math.cos(i*29)*43,[x,y]=screenPoint(wx,wy);if(x<-30||x>W+30||y<-30||y>H+30)continue;let h=hash(i,Math.floor(wx+wy));ctx.globalAlpha=.22+h*.18;ctx.fillStyle=h>.5?'#9b9b61':'#9ba17c';ctx.beginPath();ctx.ellipse(x,y,2+h*2,1.3, h*5,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
}
function drawTree(o,t){let [x,y]=screenPoint(o.x,o.y),s=o.size;if(x<-110||x>W+110||y<-200||y>H+150)return;let sway=Math.sin(t*.7+o.tone*7)*1.5;ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='rgba(4,12,10,.34)';ctx.beginPath();ctx.ellipse(6,7,43,17,-.1,0,Math.PI*2);ctx.fill();
 const trunk=ctx.createLinearGradient(-7,0,11,0);trunk.addColorStop(0,'#493e2d');trunk.addColorStop(.46,'#88704a');trunk.addColorStop(1,'#34392d');ctx.fillStyle=trunk;ctx.beginPath();ctx.moveTo(-7,-3);ctx.lineTo(-5,-52);ctx.lineTo(5,-62);ctx.lineTo(11,-2);ctx.closePath();ctx.fill();
 if(o.kind===0){for(let k=0;k<4;k++){let yy=-34-k*24,ww=47-k*8;let grad=ctx.createLinearGradient(-ww,yy-40,ww,yy+22);grad.addColorStop(0,o.tone>.5?'#385447':'#314b40');grad.addColorStop(.56,o.tone>.5?'#263f36':'#284339');grad.addColorStop(1,'#1b302c');ctx.fillStyle=grad;ctx.beginPath();ctx.moveTo(sway,yy-55);ctx.quadraticCurveTo(-ww-9,yy-4,-ww,yy+14);ctx.quadraticCurveTo(0,yy+6,ww,yy+14);ctx.quadraticCurveTo(ww-8,yy-13,sway,yy-55);ctx.fill();ctx.strokeStyle='rgba(146,153,108,.14)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(sway,yy-43);ctx.lineTo(-ww*.48,yy+7);ctx.moveTo(sway,yy-35);ctx.lineTo(ww*.48,yy+7);ctx.stroke()}}
 else{let col=o.kind===1?'#46503b':'#4a5544';for(let k=0;k<5;k++){let a=k*Math.PI*2/5+o.tone,xx=Math.cos(a)*25,yy=-87+Math.sin(a)*23;let gr=ctx.createRadialGradient(xx-8,yy-8,3,xx,yy,37);gr.addColorStop(0,o.kind===1?'#788265':'#73806b');gr.addColorStop(.55,col);gr.addColorStop(1,'#273b32');ctx.fillStyle=gr;ctx.beginPath();ctx.ellipse(xx,yy,35,30,Math.sin(a)*.3,0,Math.PI*2);ctx.fill()}ctx.fillStyle='rgba(172,170,123,.14)';ctx.beginPath();ctx.ellipse(-10,-98,13,5,-.4,0,Math.PI*2);ctx.fill()}
 ctx.restore()}
function drawRock(o){let [x,y]=screenPoint(o.x,o.y),s=o.size;if(x<-40||x>W+40||y<-60||y>H+30)return;ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='rgba(5,11,10,.33)';ctx.beginPath();ctx.ellipse(2,5,23,9,0,0,Math.PI*2);ctx.fill();let gr=ctx.createLinearGradient(-17,-18,18,8);gr.addColorStop(0,'#a4a28d');gr.addColorStop(.4,'#777e76');gr.addColorStop(1,'#444f4a');ctx.fillStyle=gr;ctx.beginPath();ctx.moveTo(-21,2);ctx.lineTo(-15,-12);ctx.lineTo(-4,-21);ctx.lineTo(12,-17);ctx.lineTo(23,-3);ctx.lineTo(17,7);ctx.lineTo(-14,8);ctx.closePath();ctx.fill();ctx.strokeStyle='rgba(226,220,192,.27)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-14,-10);ctx.lineTo(-3,-17);ctx.lineTo(4,-9);ctx.stroke();ctx.restore()}
function drawFlower(o,t){let [x,y]=screenPoint(o.x,o.y);if(x<0||x>W||y<0||y>H)return;ctx.strokeStyle='rgba(136,157,94,.58)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y+5);ctx.lineTo(x,y-4);ctx.stroke();ctx.fillStyle=o.tone>.5?'#d8c88e':'#c3cad0';for(let i=0;i<4;i++){let a=i*Math.PI/2;ctx.beginPath();ctx.ellipse(x+Math.cos(a)*2,y-5+Math.sin(a)*2,1.6,2.4,a,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#be995d';ctx.beginPath();ctx.arc(x,y-5,1.3,0,Math.PI*2);ctx.fill()}
function drawResource(o,t){let [x,y]=screenPoint(o.x,o.y);if(x<-40||x>W+40||y<-45||y>H+45)return;let bob=Math.sin(t*2+o.phase)*2;ctx.save();ctx.translate(x,y+bob);ctx.fillStyle='rgba(3,10,9,.35)';ctx.beginPath();ctx.ellipse(0,7,15,5,0,0,Math.PI*2);ctx.fill();if(o.type==='wood'){ctx.rotate(-.35);ctx.fillStyle='#886344';rr(-14,-3,27,7,3);ctx.fill();ctx.fillStyle='#c39862';ctx.beginPath();ctx.arc(-11,.5,3.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#56442f';ctx.beginPath();ctx.arc(-11,.5,1.5,0,Math.PI*2);ctx.fill()}else if(o.type==='stone'){ctx.fillStyle='#838b80';ctx.beginPath();ctx.moveTo(-11,3);ctx.lineTo(-8,-6);ctx.lineTo(-1,-10);ctx.lineTo(8,-6);ctx.lineTo(11,2);ctx.lineTo(5,6);ctx.lineTo(-7,6);ctx.closePath();ctx.fill();ctx.fillStyle='rgba(235,228,198,.45)';ctx.beginPath();ctx.moveTo(-7,-5);ctx.lineTo(-1,-9);ctx.lineTo(2,-5);ctx.fill()}else{ctx.strokeStyle='#6b8054';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,5);ctx.lineTo(0,-5);ctx.moveTo(0,0);ctx.lineTo(-6,-4);ctx.moveTo(0,-1);ctx.lineTo(6,-6);ctx.stroke();for(const [bx,by] of [[-6,-5],[1,-7],[6,-7]]){ctx.fillStyle='#ba4944';ctx.beginPath();ctx.arc(bx,by,3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e49a70';ctx.beginPath();ctx.arc(bx-1,by-1,1,0,Math.PI*2);ctx.fill()}}
 if(Math.hypot(o.x-player.x,o.y-player.y)<85){ctx.strokeStyle='rgba(227,195,131,.65)';ctx.setLineDash([2,4]);ctx.beginPath();ctx.arc(0,0,18,0,Math.PI*2);ctx.stroke();ctx.setLineDash([])}ctx.restore()}

function drawEnemy(e,t){let [x,y]=screenPoint(e.x,e.y);if(x<-60||x>W+60||y<-80||y>H+70)return;let bob=Math.sin(t*3+e.phase)*2;ctx.save();ctx.translate(x,y+bob);ctx.fillStyle='rgba(0,0,0,.4)';ctx.beginPath();ctx.ellipse(0,8,17,7,0,0,Math.PI*2);ctx.fill();let gr=ctx.createLinearGradient(-10,-20,11,7);gr.addColorStop(0,e.flash?'#e1b09a':'#879177');gr.addColorStop(1,e.flash?'#b76450':'#404b3a');ctx.fillStyle=gr;ctx.beginPath();ctx.ellipse(0,-8,12,16,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#625441';ctx.beginPath();ctx.moveTo(-8,-20);ctx.lineTo(-14,-29);ctx.lineTo(-4,-25);ctx.moveTo(7,-20);ctx.lineTo(13,-28);ctx.lineTo(4,-25);ctx.fill();ctx.fillStyle='#db9d63';ctx.beginPath();ctx.arc(-4,-12,1.8,0,Math.PI*2);ctx.arc(4,-12,1.8,0,Math.PI*2);ctx.fill();if(e.hp<e.max){ctx.fillStyle='rgba(5,10,9,.7)';rr(-15,-35,30,3,2);ctx.fill();ctx.fillStyle='#c67657';rr(-15,-35,30*e.hp/e.max,3,2);ctx.fill()}ctx.restore()}
function drawFire(f,t){let [x,y]=screenPoint(f.x,f.y),flick=Math.sin(t*11+f.phase);ctx.save();ctx.translate(x,y);let glow=ctx.createRadialGradient(0,-3,2,0,-3,110);glow.addColorStop(0,'rgba(249,157,72,.25)');glow.addColorStop(1,'rgba(242,143,57,0)');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(0,0,110,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(0,0,0,.4)';ctx.beginPath();ctx.ellipse(0,5,21,7,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#594532';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-13,2);ctx.lineTo(13,-3);ctx.moveTo(-11,-4);ctx.lineTo(10,4);ctx.stroke();ctx.fillStyle='#f8b451';ctx.beginPath();ctx.moveTo(-7,1);ctx.quadraticCurveTo(-14,-12+flick*2,-2,-23-flick*2);ctx.quadraticCurveTo(0,-13,2,-27+flick);ctx.quadraticCurveTo(14,-12,7,1);ctx.fill();ctx.fillStyle='#fff0ad';ctx.beginPath();ctx.moveTo(-3,1);ctx.quadraticCurveTo(-6,-8,1,-17);ctx.quadraticCurveTo(7,-7,4,1);ctx.fill();ctx.restore()}
function drawPlayer(t){let [x,y]=screenPoint(player.x,player.y),swing=player.swing>0?Math.sin((.38-player.swing)/.38*Math.PI):0,bob=Math.sin(player.step)*1.6;ctx.save();ctx.translate(x,y+bob);ctx.fillStyle='rgba(0,0,0,.48)';ctx.beginPath();ctx.ellipse(0,8,16,7,0,0,Math.PI*2);ctx.fill();ctx.rotate(player.dir); // character faces right in local space
 // legs animate
 ctx.strokeStyle='#534a38';ctx.lineWidth=5;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-2,1);ctx.lineTo(-4+Math.sin(player.step)*2,7);ctx.moveTo(4,1);ctx.lineTo(5-Math.sin(player.step)*2,7);ctx.stroke();
 let coat=ctx.createLinearGradient(-9,-12,10,4);coat.addColorStop(0,'#a99771');coat.addColorStop(.55,'#71634b');coat.addColorStop(1,'#403e33');ctx.fillStyle=coat;ctx.beginPath();ctx.moveTo(-9,-12);ctx.quadraticCurveTo(0,-17,9,-11);ctx.lineTo(8,3);ctx.quadraticCurveTo(0,8,-8,3);ctx.closePath();ctx.fill();ctx.fillStyle='#c6b992';ctx.beginPath();ctx.arc(2,-13,6.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#675a43';ctx.beginPath();ctx.ellipse(2,-16,7,4,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#d5c7a2';ctx.fillRect(6,-14,2,2);
 // arm & weapon
 ctx.strokeStyle='#b89e72';ctx.lineWidth=3.5;ctx.beginPath();ctx.moveTo(4,-8);ctx.lineTo(10,-5-swing*9);ctx.stroke();ctx.strokeStyle='#846544';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(10,-5-swing*9);ctx.lineTo(20,-8-swing*12);ctx.stroke();ctx.fillStyle=bag.axe?'#b8b7a3':'#9c8058';ctx.beginPath();ctx.moveTo(17,-9-swing*12);ctx.lineTo(19,-16-swing*12);ctx.lineTo(28,-18-swing*12);ctx.lineTo(25,-10-swing*12);ctx.closePath();ctx.fill();if(player.flash>0){ctx.strokeStyle=`rgba(255,235,174,${player.flash*5})`;ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,-4,30+swing*13,-.7,.7);ctx.stroke()}ctx.restore()}
